package vn.edu.hunre.nhom11.carrental.dashboard.api;import java.util.Map;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import vn.edu.hunre.nhom11.carrental.booking.domain.BookingStatus;import vn.edu.hunre.nhom11.carrental.booking.repository.BookingRepository;import vn.edu.hunre.nhom11.carrental.catalog.repository.CarRepository;import vn.edu.hunre.nhom11.carrental.identity.repository.UserRepository;import vn.edu.hunre.nhom11.carrental.payment.repository.PaymentRepository;@RestController@RequestMapping("/api/dashboard")@PreAuthorize("hasRole('ADMIN')")public class DashboardController{private final UserRepository users;private final CarRepository cars;private final BookingRepository bookings;private final PaymentRepository payments;public DashboardController(UserRepository u,CarRepository c,BookingRepository b,PaymentRepository p){users=u;cars=c;bookings=b;payments=p;}@GetMapping Object stats(){return Map.of("users",users.count(),"cars",cars.count(),"bookings",bookings.count(),"pendingBookings",bookings.countByStatus(BookingStatus.PENDING),"revenue",payments.totalRevenue());}}

